program='''def _maximal_rectangles(grid):
    rows, cols = len(grid), len(grid[0])
    rectangles = []
    for top in range(rows):
        solid = [True] * cols
        for bottom in range(top, rows):
            solid = [solid[c] and grid[bottom][c] != 0 for c in range(cols)]
            c = 0
            while c < cols:
                if not solid[c]:
                    c += 1
                    continue
                left = c
                while c < cols and solid[c]:
                    c += 1
                right = c - 1
                if top > 0 and all(grid[top - 1][x] != 0 for x in range(left, right + 1)):
                    continue
                if bottom + 1 < rows and all(grid[bottom + 1][x] != 0 for x in range(left, right + 1)):
                    continue
                rectangles.append((top, left, bottom, right))
    return rectangles


def transform(grid):
    rows, cols = len(grid), len(grid[0])
    component = {}
    colors = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 or (r, c) in component:
                continue
            index = len(colors)
            component[r, c] = index
            stack = [(r, c)]
            color = None
            while stack:
                x, y = stack.pop()
                if grid[x][y] > 1 and color is None:
                    color = grid[x][y]
                for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != 0 and (nx, ny) not in component:
                        component[nx, ny] = index
                        stack.append((nx, ny))
            colors.append(color)

    result = [row[:] for row in grid]
    for top, left, bottom, right in _maximal_rectangles(grid):
        if bottom - top < 2 or right - left < 2:
            continue
        color = colors[component[top, left]]
        if color is None:
            continue
        for r in range(top + 1, bottom):
            for c in range(left + 1, right):
                if result[r][c] == 1:
                    result[r][c] = color
    return result
'''
